export interface CrmWorkspaceLifecycleRecords {
  /**
   * reset or delete destructive workspace action.
   */
  action: string;
  /**
   * Acting owner identity snapshot; deliberately not a foreign key.
   */
  actor_user_id: string;
  /**
   * Timestamp when every captured object was removed.
   */
  cleanup_completed_at: Timestamp | null;
  /**
   * pending or complete object cleanup state.
   */
  cleanup_status: Generated<string>;
  /**
   * Creation timestamp in UTC.
   */
  created_at: Generated<Timestamp>;
  /**
   * Stable lifecycle record and cleanup receipt identifier.
   */
  id: Generated<string>;
  /**
   * Non-identifying counts confirmed by the owner before the action.
   */
  impact_counts: Generated<Json>;
  /**
   * Internal object keys required only until cleanup completes.
   */
  object_keys: Generated<Json>;
  /**
   * Atomic destructive database action timestamp.
   */
  occurred_at: Timestamp;
  /**
   * Redacted result of a destructive workspace attempt.
   */
  outcome: string;
  /**
   * Affected workspace identifier snapshot; deliberately not a foreign key.
   */
  workspace_id: string;
}

